-- Inventory organ -- generated by noctusai_lib.domain.inventory.sql (do not hand-edit)

SET search_path = commerce, public;

-- Warehouses. One default per org (partial unique index); never deleted, only deactivated.
CREATE TABLE IF NOT EXISTS commerce.inv_warehouses (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    org_id      UUID NOT NULL,
    name        TEXT NOT NULL,
    code        TEXT NOT NULL,
    is_default  BOOLEAN NOT NULL DEFAULT false,
    address     JSONB NOT NULL DEFAULT '{}'::jsonb,
    active      BOOLEAN NOT NULL DEFAULT true,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (btrim(name) <> '' AND btrim(code) <> ''),
    CHECK (NOT (is_default AND NOT active))
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_inv_warehouses_code ON commerce.inv_warehouses (org_id, lower(code));
CREATE UNIQUE INDEX IF NOT EXISTS uq_inv_warehouses_default ON commerce.inv_warehouses (org_id) WHERE is_default;
ALTER TABLE commerce.inv_warehouses ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "inv_warehouses_select_own_org" ON commerce.inv_warehouses;
CREATE POLICY "inv_warehouses_select_own_org" ON commerce.inv_warehouses FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.inv_warehouses;
CREATE POLICY "service_role_bypass" ON commerce.inv_warehouses FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Per item x warehouse settings (the low-stock threshold).
CREATE TABLE IF NOT EXISTS commerce.inv_item_settings (
    org_id        UUID NOT NULL,
    item_id       UUID NOT NULL REFERENCES commerce.itm_items(id) ON DELETE RESTRICT,
    warehouse_id  UUID NOT NULL REFERENCES commerce.inv_warehouses(id) ON DELETE RESTRICT,
    min_qty       NUMERIC(18,3) NOT NULL DEFAULT 0 CHECK (min_qty >= 0),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (org_id, item_id, warehouse_id)
);
ALTER TABLE commerce.inv_item_settings ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "inv_item_settings_select_own_org" ON commerce.inv_item_settings;
CREATE POLICY "inv_item_settings_select_own_org" ON commerce.inv_item_settings FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.inv_item_settings;
CREATE POLICY "service_role_bypass" ON commerce.inv_item_settings FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Balances: the cache the kardex explains. The CHECKs are the overselling backstop (stock=1 pieces).
CREATE TABLE IF NOT EXISTS commerce.inv_stock_balances (
    org_id         UUID NOT NULL,
    item_id        UUID NOT NULL REFERENCES commerce.itm_items(id) ON DELETE RESTRICT,
    warehouse_id   UUID NOT NULL REFERENCES commerce.inv_warehouses(id) ON DELETE RESTRICT,
    on_hand        NUMERIC(18,3) NOT NULL DEFAULT 0,
    reserved       NUMERIC(18,3) NOT NULL DEFAULT 0,
    avg_cost_cents BIGINT NOT NULL DEFAULT 0 CHECK (avg_cost_cents >= 0),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (org_id, item_id, warehouse_id),
    CONSTRAINT inv_stock_balances_reserved_nonneg CHECK (reserved >= 0),
    CONSTRAINT inv_stock_balances_available_nonneg CHECK (on_hand - reserved >= 0)
);
CREATE INDEX IF NOT EXISTS idx_inv_stock_balances_wh ON commerce.inv_stock_balances (org_id, warehouse_id);
ALTER TABLE commerce.inv_stock_balances ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "inv_stock_balances_select_own_org" ON commerce.inv_stock_balances;
CREATE POLICY "inv_stock_balances_select_own_org" ON commerce.inv_stock_balances FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.inv_stock_balances;
CREATE POLICY "service_role_bypass" ON commerce.inv_stock_balances FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Stock moves (APPEND-ONLY kardex). `seq` orders the history; *_after columns make the running balance a read. adjust.qty is the signed delta; every other kind is > 0.
CREATE TABLE IF NOT EXISTS commerce.inv_stock_moves (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    seq                   BIGINT GENERATED ALWAYS AS IDENTITY,
    org_id                UUID NOT NULL,
    item_id               UUID NOT NULL REFERENCES commerce.itm_items(id) ON DELETE RESTRICT,
    warehouse_id          UUID NOT NULL REFERENCES commerce.inv_warehouses(id) ON DELETE RESTRICT,
    kind                  TEXT NOT NULL CHECK (kind IN ('in', 'out', 'adjust', 'transfer_in', 'transfer_out', 'reserve', 'release', 'commit')),
    qty                   NUMERIC(18,3) NOT NULL,
    unit_cost_cents       BIGINT NOT NULL DEFAULT 0 CHECK (unit_cost_cents >= 0),
    source                TEXT NOT NULL DEFAULT 'manual',
    source_ref            TEXT,
    transfer_group        UUID,
    note                  TEXT,
    on_hand_after         NUMERIC(18,3) NOT NULL,
    reserved_after        NUMERIC(18,3) NOT NULL,
    avg_cost_after_cents  BIGINT NOT NULL,
    occurred_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by            UUID,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    CHECK (qty <> 0),
    CHECK (kind = 'adjust' OR qty > 0),
    CHECK (source_ref IS NULL OR btrim(source_ref) <> ''),
    CHECK ((kind IN ('transfer_in', 'transfer_out')) = (transfer_group IS NOT NULL))
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_inv_stock_moves_idem
    ON commerce.inv_stock_moves (org_id, source, source_ref, kind, item_id, warehouse_id) WHERE source_ref IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_inv_stock_moves_item ON commerce.inv_stock_moves (org_id, item_id, warehouse_id, seq);
CREATE INDEX IF NOT EXISTS idx_inv_stock_moves_ref ON commerce.inv_stock_moves (org_id, source, source_ref) WHERE source_ref IS NOT NULL;

CREATE OR REPLACE FUNCTION commerce.inv_stock_moves_append_only() RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
BEGIN
    RAISE EXCEPTION 'inv_stock_moves is append-only (% refused)', TG_OP USING ERRCODE = 'IN002';
END;
$fn$;
DROP TRIGGER IF EXISTS inv_stock_moves_no_update_delete ON commerce.inv_stock_moves;
CREATE TRIGGER inv_stock_moves_no_update_delete BEFORE UPDATE OR DELETE ON commerce.inv_stock_moves
    FOR EACH ROW EXECUTE FUNCTION commerce.inv_stock_moves_append_only();
DROP TRIGGER IF EXISTS inv_stock_moves_no_truncate ON commerce.inv_stock_moves;
CREATE TRIGGER inv_stock_moves_no_truncate BEFORE TRUNCATE ON commerce.inv_stock_moves
    FOR EACH STATEMENT EXECUTE FUNCTION commerce.inv_stock_moves_append_only();
ALTER TABLE commerce.inv_stock_moves ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "inv_stock_moves_select_own_org" ON commerce.inv_stock_moves;
CREATE POLICY "inv_stock_moves_select_own_org" ON commerce.inv_stock_moves FOR SELECT TO authenticated
  USING (org_id = (SELECT public.current_org_id_for('commerce')));
DROP POLICY IF EXISTS "service_role_bypass" ON commerce.inv_stock_moves;
CREATE POLICY "service_role_bypass" ON commerce.inv_stock_moves FOR ALL TO service_role USING (true) WITH CHECK (true);

-- Row-locked stock mutations: lock the balance, write the kardex move AND the balance in ONE transaction.

CREATE OR REPLACE FUNCTION commerce.inv_lock_balance(p_org UUID, p_item UUID, p_wh UUID) RETURNS commerce.inv_stock_balances
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE v_bal commerce.inv_stock_balances%ROWTYPE;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM commerce.inv_warehouses WHERE id = p_wh AND org_id = p_org) THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'deposito_invalido';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM commerce.itm_items WHERE id = p_item AND org_id = p_org) THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'item_invalido', DETAIL = p_item::text;
    END IF;
    INSERT INTO commerce.inv_stock_balances (org_id, item_id, warehouse_id) VALUES (p_org, p_item, p_wh) ON CONFLICT DO NOTHING;
    SELECT * INTO v_bal FROM commerce.inv_stock_balances WHERE org_id = p_org AND item_id = p_item AND warehouse_id = p_wh FOR UPDATE;
    RETURN v_bal;
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.inv_lock_balance(UUID, UUID, UUID) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.inv_lock_balance(UUID, UUID, UUID) TO service_role;

CREATE OR REPLACE FUNCTION commerce.inv_apply_move(p_org UUID, p_item UUID, p_wh UUID, p_kind TEXT, p_qty NUMERIC, p_cost BIGINT, p_source TEXT, p_ref TEXT, p_user UUID, p_note TEXT, p_group UUID, p_occurred TIMESTAMPTZ) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    v_bal  commerce.inv_stock_balances%ROWTYPE;
    v_prev commerce.inv_stock_moves%ROWTYPE;
    v_move commerce.inv_stock_moves%ROWTYPE;
    v_on   NUMERIC; v_res NUMERIC; v_avg BIGINT; v_cost BIGINT;
BEGIN
    IF p_qty IS NULL OR p_qty = 0 OR (p_kind <> 'adjust' AND p_qty < 0) THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_invalida', DETAIL = p_item::text;
    END IF;
    IF p_cost IS NOT NULL AND p_cost < 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'custo_invalido', DETAIL = p_item::text;
    END IF;
    v_bal := commerce.inv_lock_balance(p_org, p_item, p_wh);
    IF p_ref IS NOT NULL THEN
        SELECT * INTO v_prev FROM commerce.inv_stock_moves
            WHERE org_id = p_org AND source = p_source AND source_ref = p_ref AND kind = p_kind
              AND item_id = p_item AND warehouse_id = p_wh;
        IF FOUND THEN
            RETURN jsonb_build_object('replayed', true, 'move', to_jsonb(v_prev));
        END IF;
    END IF;
    v_on := v_bal.on_hand; v_res := v_bal.reserved; v_avg := v_bal.avg_cost_cents; v_cost := v_avg;
    IF p_kind IN ('in', 'transfer_in') OR (p_kind = 'adjust' AND p_qty > 0) THEN
        IF p_kind <> 'adjust' AND p_cost IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'custo_invalido', DETAIL = p_item::text;
        END IF;
        v_cost := COALESCE(p_cost, v_avg);
        v_avg := round((v_on * v_avg + p_qty * v_cost) / (v_on + p_qty))::bigint;
        v_on := v_on + p_qty;
    ELSIF p_kind IN ('out', 'transfer_out') THEN
        IF v_on - v_res < p_qty THEN
            RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'estoque_insuficiente', DETAIL = p_item::text;
        END IF;
        v_on := v_on - p_qty;
    ELSIF p_kind = 'adjust' THEN
        IF v_on + p_qty < v_res THEN
            RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'abaixo_reservado', DETAIL = p_item::text;
        END IF;
        v_on := v_on + p_qty;
    ELSIF p_kind = 'reserve' THEN
        IF v_on - v_res < p_qty THEN
            RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'estoque_insuficiente', DETAIL = p_item::text;
        END IF;
        v_res := v_res + p_qty;
    ELSIF p_kind = 'release' THEN
        IF v_res < p_qty THEN
            RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_divergente', DETAIL = p_item::text;
        END IF;
        v_res := v_res - p_qty;
    ELSIF p_kind = 'commit' THEN
        IF v_res < p_qty THEN
            RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_divergente', DETAIL = p_item::text;
        END IF;
        v_res := v_res - p_qty;
        v_on := v_on - p_qty;
    ELSE
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_invalida', DETAIL = p_item::text;
    END IF;
    UPDATE commerce.inv_stock_balances SET on_hand = v_on, reserved = v_res, avg_cost_cents = v_avg, updated_at = now()
        WHERE org_id = p_org AND item_id = p_item AND warehouse_id = p_wh;
    INSERT INTO commerce.inv_stock_moves (org_id, item_id, warehouse_id, kind, qty, unit_cost_cents, source, source_ref, transfer_group, note,
                      on_hand_after, reserved_after, avg_cost_after_cents, occurred_at, created_by)
        VALUES (p_org, p_item, p_wh, p_kind, p_qty, v_cost, p_source, p_ref, p_group, p_note,
                v_on, v_res, v_avg, COALESCE(p_occurred, now()), p_user)
        RETURNING * INTO v_move;
    RETURN jsonb_build_object('replayed', false, 'move', to_jsonb(v_move));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.inv_apply_move(UUID, UUID, UUID, TEXT, NUMERIC, BIGINT, TEXT, TEXT, UUID, TEXT, UUID, TIMESTAMPTZ) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.inv_apply_move(UUID, UUID, UUID, TEXT, NUMERIC, BIGINT, TEXT, TEXT, UUID, TEXT, UUID, TIMESTAMPTZ) TO service_role;

CREATE OR REPLACE FUNCTION commerce.inv_receive(p_org UUID, p_row JSONB) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE v_res JSONB; v_code TEXT; v_item TEXT;
BEGIN
    v_res := commerce.inv_apply_move(
        p_org, (p_row->>'item_id')::uuid, (p_row->>'warehouse_id')::uuid, 'in', (p_row->>'qty')::numeric, (p_row->>'unit_cost_cents')::bigint,
        COALESCE(p_row->>'source', 'manual'), NULLIF(p_row->>'source_ref', ''), (p_row->>'created_by')::uuid,
        p_row->>'note', NULL, (p_row->>'occurred_at')::timestamptz);
    RETURN jsonb_build_object('status', CASE WHEN (v_res->>'replayed')::boolean THEN 'replayed' ELSE 'ok' END,
                              'moves', jsonb_build_array(v_res->'move'));
EXCEPTION WHEN SQLSTATE 'IN001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_item = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'item_id', NULLIF(v_item, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.inv_receive(UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.inv_receive(UUID, JSONB) TO service_role;

CREATE OR REPLACE FUNCTION commerce.inv_issue(p_org UUID, p_row JSONB) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE v_res JSONB; v_code TEXT; v_item TEXT;
BEGIN
    v_res := commerce.inv_apply_move(
        p_org, (p_row->>'item_id')::uuid, (p_row->>'warehouse_id')::uuid, 'out', (p_row->>'qty')::numeric, NULL,
        COALESCE(p_row->>'source', 'manual'), NULLIF(p_row->>'source_ref', ''), (p_row->>'created_by')::uuid,
        p_row->>'note', NULL, (p_row->>'occurred_at')::timestamptz);
    RETURN jsonb_build_object('status', CASE WHEN (v_res->>'replayed')::boolean THEN 'replayed' ELSE 'ok' END,
                              'moves', jsonb_build_array(v_res->'move'));
EXCEPTION WHEN SQLSTATE 'IN001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_item = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'item_id', NULLIF(v_item, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.inv_issue(UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.inv_issue(UUID, JSONB) TO service_role;

CREATE OR REPLACE FUNCTION commerce.inv_adjust(p_org UUID, p_row JSONB) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    v_res JSONB; v_code TEXT; v_item TEXT;
    v_item_id UUID := (p_row->>'item_id')::uuid; v_wh UUID := (p_row->>'warehouse_id')::uuid;
    v_bal commerce.inv_stock_balances%ROWTYPE; v_counted NUMERIC := (p_row->>'counted_qty')::numeric; v_delta NUMERIC;
    v_src TEXT := COALESCE(p_row->>'source', 'manual'); v_ref TEXT := NULLIF(p_row->>'source_ref', '');
    v_prev commerce.inv_stock_moves%ROWTYPE;
BEGIN
    IF v_counted IS NULL OR v_counted < 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_invalida', DETAIL = v_item_id::text;
    END IF;
    v_bal := commerce.inv_lock_balance(p_org, v_item_id, v_wh);
    IF v_ref IS NOT NULL THEN
        SELECT * INTO v_prev FROM commerce.inv_stock_moves
            WHERE org_id = p_org AND source = v_src AND source_ref = v_ref AND kind = 'adjust'
              AND item_id = v_item_id AND warehouse_id = v_wh;
        IF FOUND THEN
            RETURN jsonb_build_object('status', 'replayed', 'moves', jsonb_build_array(to_jsonb(v_prev)));
        END IF;
    END IF;
    v_delta := v_counted - v_bal.on_hand;
    IF v_delta = 0 THEN
        RETURN jsonb_build_object('status', 'ok', 'moves', '[]'::jsonb);
    END IF;
    v_res := commerce.inv_apply_move(
        p_org, v_item_id, v_wh, 'adjust', v_delta, (p_row->>'unit_cost_cents')::bigint, v_src, v_ref,
        (p_row->>'created_by')::uuid, p_row->>'note', NULL, (p_row->>'occurred_at')::timestamptz);
    RETURN jsonb_build_object('status', 'ok', 'moves', jsonb_build_array(v_res->'move'));
EXCEPTION WHEN SQLSTATE 'IN001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_item = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'item_id', NULLIF(v_item, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.inv_adjust(UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.inv_adjust(UUID, JSONB) TO service_role;

CREATE OR REPLACE FUNCTION commerce.inv_transfer(p_org UUID, p_row JSONB) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    v_out JSONB; v_in JSONB; v_code TEXT; v_item TEXT;
    v_item_id UUID := (p_row->>'item_id')::uuid;
    v_from UUID := (p_row->>'from_warehouse_id')::uuid; v_to UUID := (p_row->>'to_warehouse_id')::uuid;
    v_src TEXT := COALESCE(p_row->>'source', 'manual'); v_ref TEXT := NULLIF(p_row->>'source_ref', '');
    v_qty NUMERIC := (p_row->>'qty')::numeric; v_when TIMESTAMPTZ := (p_row->>'occurred_at')::timestamptz;
    v_user UUID := (p_row->>'created_by')::uuid; v_note TEXT := p_row->>'note';
BEGIN
    IF v_from = v_to THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'transferencia_mesmo_deposito', DETAIL = v_item_id::text;
    END IF;
    PERFORM commerce.inv_lock_balance(p_org, v_item_id, LEAST(v_from, v_to));
    PERFORM commerce.inv_lock_balance(p_org, v_item_id, GREATEST(v_from, v_to));
    v_out := commerce.inv_apply_move(p_org, v_item_id, v_from, 'transfer_out', v_qty, NULL, v_src, v_ref, v_user, v_note,
                                   gen_random_uuid(), v_when);
    v_in := commerce.inv_apply_move(p_org, v_item_id, v_to, 'transfer_in', v_qty, (v_out->'move'->>'unit_cost_cents')::bigint,
                                  v_src, v_ref, v_user, v_note, (v_out->'move'->>'transfer_group')::uuid, v_when);
    RETURN jsonb_build_object('status', CASE WHEN (v_out->>'replayed')::boolean THEN 'replayed' ELSE 'ok' END,
                              'moves', jsonb_build_array(v_out->'move', v_in->'move'));
EXCEPTION WHEN SQLSTATE 'IN001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_item = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'item_id', NULLIF(v_item, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.inv_transfer(UUID, JSONB) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.inv_transfer(UUID, JSONB) TO service_role;

CREATE OR REPLACE FUNCTION commerce.inv_reserve(p_org UUID, p_order_ref TEXT, p_lines JSONB, p_user UUID, p_source TEXT) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    r RECORD; v_res JSONB; v_code TEXT; v_item TEXT; v_moves JSONB := '[]'::jsonb; v_all_replayed BOOLEAN := true;
    v_default UUID;
BEGIN
    IF p_order_ref IS NULL OR btrim(p_order_ref) = '' OR p_lines IS NULL OR jsonb_array_length(p_lines) = 0 THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_invalida';
    END IF;
    SELECT id INTO v_default FROM commerce.inv_warehouses WHERE org_id = p_org AND is_default AND active;
    FOR r IN
        SELECT (l->>'item_id')::uuid AS item_id, COALESCE((l->>'warehouse_id')::uuid, v_default) AS warehouse_id,
               sum((l->>'qty')::numeric) AS qty
        FROM jsonb_array_elements(p_lines) l GROUP BY 1, 2 ORDER BY 1, 2
    LOOP
        IF r.warehouse_id IS NULL THEN
            RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'sem_deposito_padrao', DETAIL = r.item_id::text;
        END IF;
        v_res := commerce.inv_apply_move(p_org, r.item_id, r.warehouse_id, 'reserve', r.qty, NULL, COALESCE(p_source, 'order'),
                                       p_order_ref, p_user, NULL, NULL, NULL);
        v_all_replayed := v_all_replayed AND (v_res->>'replayed')::boolean;
        v_moves := v_moves || jsonb_build_array(v_res->'move');
    END LOOP;
    RETURN jsonb_build_object('status', CASE WHEN v_all_replayed THEN 'replayed' ELSE 'ok' END, 'moves', v_moves);
EXCEPTION WHEN SQLSTATE 'IN001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_item = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'item_id', NULLIF(v_item, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.inv_reserve(UUID, TEXT, JSONB, UUID, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.inv_reserve(UUID, TEXT, JSONB, UUID, TEXT) TO service_role;

CREATE OR REPLACE FUNCTION commerce.inv_commit(p_org UUID, p_order_ref TEXT, p_lines JSONB, p_user UUID, p_source TEXT) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    r RECORD; l JSONB; v_res JSONB; v_code TEXT; v_item TEXT; v_moves JSONB := '[]'::jsonb; v_all_replayed BOOLEAN := true;
    v_any BOOLEAN := false; v_src TEXT := COALESCE(p_source, 'order'); v_reserved NUMERIC; v_line_item UUID;
    v_filter BOOLEAN := p_lines IS NOT NULL AND jsonb_array_length(p_lines) > 0;
BEGIN
    IF p_order_ref IS NULL OR btrim(p_order_ref) = '' THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_invalida';
    END IF;
    IF v_filter THEN
        FOR l IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
            v_line_item := (l->>'item_id')::uuid;
            SELECT sum(qty) INTO v_reserved FROM commerce.inv_stock_moves
                WHERE org_id = p_org AND source = v_src AND source_ref = p_order_ref AND kind = 'reserve' AND item_id = v_line_item;
            IF v_reserved IS NULL THEN
                RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'sem_reserva', DETAIL = v_line_item::text;
            ELSIF l->>'qty' IS NOT NULL AND (l->>'qty')::numeric <> v_reserved THEN
                RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_divergente', DETAIL = v_line_item::text;
            END IF;
        END LOOP;
    END IF;
    FOR r IN
        SELECT m.item_id, m.warehouse_id, m.qty FROM commerce.inv_stock_moves m
        WHERE m.org_id = p_org AND m.source = v_src AND m.source_ref = p_order_ref AND m.kind = 'reserve'
          AND (NOT v_filter OR m.item_id IN (SELECT (x->>'item_id')::uuid FROM jsonb_array_elements(p_lines) x))
        ORDER BY m.item_id, m.warehouse_id
    LOOP
        v_any := true;
        IF NOT EXISTS (SELECT 1 FROM commerce.inv_stock_moves WHERE org_id = p_org AND source = v_src AND source_ref = p_order_ref
                       AND kind = 'commit' AND item_id = r.item_id AND warehouse_id = r.warehouse_id)
           AND EXISTS (SELECT 1 FROM commerce.inv_stock_moves WHERE org_id = p_org AND source = v_src AND source_ref = p_order_ref
                       AND kind = 'release' AND item_id = r.item_id AND warehouse_id = r.warehouse_id) THEN
            RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'reserva_liberada', DETAIL = r.item_id::text;
        END IF;
        v_res := commerce.inv_apply_move(p_org, r.item_id, r.warehouse_id, 'commit', r.qty, NULL, v_src, p_order_ref, p_user,
                                       NULL, NULL, NULL);
        v_all_replayed := v_all_replayed AND (v_res->>'replayed')::boolean;
        v_moves := v_moves || jsonb_build_array(v_res->'move');
    END LOOP;
    IF NOT v_any THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'sem_reserva';
    END IF;
    RETURN jsonb_build_object('status', CASE WHEN v_all_replayed THEN 'replayed' ELSE 'ok' END, 'moves', v_moves);
EXCEPTION WHEN SQLSTATE 'IN001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_item = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'item_id', NULLIF(v_item, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.inv_commit(UUID, TEXT, JSONB, UUID, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.inv_commit(UUID, TEXT, JSONB, UUID, TEXT) TO service_role;

CREATE OR REPLACE FUNCTION commerce.inv_release(p_org UUID, p_order_ref TEXT, p_lines JSONB, p_user UUID, p_source TEXT) RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, commerce, pg_temp
AS $fn$
DECLARE
    r RECORD; l JSONB; v_res JSONB; v_code TEXT; v_item TEXT; v_moves JSONB := '[]'::jsonb; v_all_replayed BOOLEAN := true;
    v_any BOOLEAN := false; v_src TEXT := COALESCE(p_source, 'order'); v_reserved NUMERIC; v_line_item UUID;
    v_filter BOOLEAN := p_lines IS NOT NULL AND jsonb_array_length(p_lines) > 0;
BEGIN
    IF p_order_ref IS NULL OR btrim(p_order_ref) = '' THEN
        RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_invalida';
    END IF;
    IF v_filter THEN
        FOR l IN SELECT * FROM jsonb_array_elements(p_lines) LOOP
            v_line_item := (l->>'item_id')::uuid;
            SELECT sum(qty) INTO v_reserved FROM commerce.inv_stock_moves
                WHERE org_id = p_org AND source = v_src AND source_ref = p_order_ref AND kind = 'reserve' AND item_id = v_line_item;
            IF v_reserved IS NULL THEN
                CONTINUE;
            ELSIF l->>'qty' IS NOT NULL AND (l->>'qty')::numeric <> v_reserved THEN
                RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'quantidade_divergente', DETAIL = v_line_item::text;
            END IF;
        END LOOP;
    END IF;
    FOR r IN
        SELECT m.item_id, m.warehouse_id, m.qty FROM commerce.inv_stock_moves m
        WHERE m.org_id = p_org AND m.source = v_src AND m.source_ref = p_order_ref AND m.kind = 'reserve'
          AND (NOT v_filter OR m.item_id IN (SELECT (x->>'item_id')::uuid FROM jsonb_array_elements(p_lines) x))
        ORDER BY m.item_id, m.warehouse_id
    LOOP
        v_any := true;
        IF NOT EXISTS (SELECT 1 FROM commerce.inv_stock_moves WHERE org_id = p_org AND source = v_src AND source_ref = p_order_ref
                       AND kind = 'release' AND item_id = r.item_id AND warehouse_id = r.warehouse_id)
           AND EXISTS (SELECT 1 FROM commerce.inv_stock_moves WHERE org_id = p_org AND source = v_src AND source_ref = p_order_ref
                       AND kind = 'commit' AND item_id = r.item_id AND warehouse_id = r.warehouse_id) THEN
            RAISE EXCEPTION USING ERRCODE = 'IN001', MESSAGE = 'reserva_consumida', DETAIL = r.item_id::text;
        END IF;
        v_res := commerce.inv_apply_move(p_org, r.item_id, r.warehouse_id, 'release', r.qty, NULL, v_src, p_order_ref, p_user,
                                       NULL, NULL, NULL);
        v_all_replayed := v_all_replayed AND (v_res->>'replayed')::boolean;
        v_moves := v_moves || jsonb_build_array(v_res->'move');
    END LOOP;
    IF NOT v_any THEN
        RETURN jsonb_build_object('status', 'ok', 'moves', '[]'::jsonb);
    END IF;
    RETURN jsonb_build_object('status', CASE WHEN v_all_replayed THEN 'replayed' ELSE 'ok' END, 'moves', v_moves);
EXCEPTION WHEN SQLSTATE 'IN001' THEN
    GET STACKED DIAGNOSTICS v_code = MESSAGE_TEXT, v_item = PG_EXCEPTION_DETAIL;
    RETURN jsonb_build_object('status', 'refused', 'code', v_code, 'item_id', NULLIF(v_item, ''));
END;
$fn$;
REVOKE ALL ON FUNCTION commerce.inv_release(UUID, TEXT, JSONB, UUID, TEXT) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION commerce.inv_release(UUID, TEXT, JSONB, UUID, TEXT) TO service_role;
